			&OutlineEntry;
			&JavascriptReportFilter;
			/* <flatten type="Javascript"> */
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}

function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			var d1 = f.getItem('tu_ngay').value;
			var d2 = f.getItem('den_ngay').value;
			var tt = f.getItem('tinh_trang').options[f.getItem('tinh_trang').selectedIndex].innerText;
			var isCreated = f.getItem('isCreated').options[f.getItem('isCreated').selectedIndex].innerText;
			g._alterTitle = [null, [['%d1', d1, true], ['%d2', d2, true], ['%tt', tt, true], ['%isCreated', isCreated, true] ]];
			break;
		default:
			 break;
	}
}

